var RK_BASE=256n, RK_MOD=1000000007n;
function rkHash(s){
  var h=0n;
  for(var i=0;i<s.length;i++) h=(h*RK_BASE+BigInt(s.charCodeAt(i)))%RK_MOD;
  return Number(h);
}
function rkPow(b,e,mod){
  var bb=BigInt(b)%BigInt(mod), mm=BigInt(mod), r=1n, ee=BigInt(e);
  while(ee>0n){ if(ee%2n===1n) r=(r*bb)%mm; bb=(bb*bb)%mm; ee/=2n; }
  return Number(r);
}
function rkSearch(text, pattern){
  if(typeof text!=='string'||typeof pattern!=='string') return { value:null, error:'输入必须是字符串' };
  if(!pattern.length) return { value:null, error:'模式为空' };
  var n=text.length, m=pattern.length;
  if(m>n) return { value:[], error:null };
  var ph=BigInt(rkHash(pattern)), th=BigInt(rkHash(text.slice(0,m)));
  var top=BigInt(rkPow(256,m-1,1000000007));
  var out=[], comparisons=0;
  for(var i=0;;i++){
    if(th===ph){
      comparisons++;
      if(text.substr(i,m)===pattern) out.push(i);
    }
    if(i+m>=n) break;
    th=(th-BigInt(text.charCodeAt(i))*top%RK_MOD+RK_MOD)%RK_MOD;
    th=(th*RK_BASE+BigInt(text.charCodeAt(i+m)))%RK_MOD;
  }
  return { value:out, error:null, comparisons:comparisons };
}
function rkSearchMulti(text, patterns){
  if(!Array.isArray(patterns)||!patterns.length) return { value:null, error:'模式列表为空' };
  var res={};
  for(var i=0;i<patterns.length;i++){
    var p=patterns[i];
    var r=rkSearch(text, p);
    if(r.error) return { value:null, error:'"'+p+'": '+r.error };
    res[p]=r.value;
  }
  return { value:res, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { rkHash:rkHash, rkPow:rkPow, rkSearch:rkSearch, rkSearchMulti:rkSearchMulti };
}
if (typeof window !== 'undefined') {
  window.RabinForgePure = { rkHash:rkHash, rkPow:rkPow, rkSearch:rkSearch, rkSearchMulti:rkSearchMulti };
}
